CREATE SEQUENCE ducklake_data_file_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE SEQUENCE ducklake_delete_file_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE SEQUENCE ducklake_partition_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE SEQUENCE ducklake_schema_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE SEQUENCE ducklake_sort_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE SEQUENCE ducklake_table_id_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE TABLE ducklake_column(column_id BIGINT, begin_snapshot BIGINT, end_snapshot BIGINT, table_id BIGINT, column_order BIGINT, column_name VARCHAR, column_type VARCHAR, initial_default VARCHAR, default_value VARCHAR, nulls_allowed BOOLEAN, parent_column BIGINT, default_value_type VARCHAR, default_value_dialect VARCHAR);;
CREATE TABLE ducklake_column_mapping(mapping_id BIGINT, table_id BIGINT, "type" VARCHAR);;
CREATE TABLE ducklake_column_tag(table_id BIGINT, column_id BIGINT, begin_snapshot BIGINT, end_snapshot BIGINT, "key" VARCHAR, "value" VARCHAR);;
CREATE TABLE ducklake_data_file(data_file_id BIGINT DEFAULT(nextval('ducklake_data_file_id_seq')) PRIMARY KEY, table_id BIGINT NOT NULL, path VARCHAR NOT NULL, path_is_relative BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL, file_size_bytes BIGINT NOT NULL, footer_size BIGINT, encryption_key VARCHAR, record_count BIGINT, row_id_start BIGINT, mapping_id BIGINT, begin_snapshot BIGINT NOT NULL, end_snapshot BIGINT, file_order BIGINT, file_format VARCHAR, partial_max BIGINT, partition_id BIGINT);;
CREATE TABLE ducklake_delete_file(delete_file_id BIGINT DEFAULT(nextval('ducklake_delete_file_id_seq')) PRIMARY KEY, data_file_id BIGINT NOT NULL, table_id BIGINT NOT NULL, path VARCHAR NOT NULL, path_is_relative BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL, format VARCHAR, file_size_bytes BIGINT NOT NULL, footer_size BIGINT, encryption_key VARCHAR, delete_count BIGINT, begin_snapshot BIGINT NOT NULL, end_snapshot BIGINT, partial_max BIGINT);;
CREATE TABLE ducklake_files_scheduled_for_deletion(data_file_id BIGINT NOT NULL, path VARCHAR NOT NULL, path_is_relative BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL, schedule_start TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));;
CREATE TABLE ducklake_file_column_stats(data_file_id BIGINT NOT NULL, table_id BIGINT NOT NULL, column_id BIGINT NOT NULL, column_size_bytes BIGINT, value_count BIGINT, null_count BIGINT, min_value VARCHAR, max_value VARCHAR, contains_nan BOOLEAN, extra_stats VARCHAR);;
CREATE TABLE ducklake_file_partition_value(data_file_id BIGINT NOT NULL, table_id BIGINT NOT NULL, partition_key_index BIGINT NOT NULL, partition_value VARCHAR);;
CREATE TABLE ducklake_file_variant_stats(data_file_id BIGINT, table_id BIGINT, column_id BIGINT, variant_path VARCHAR, shredded_type VARCHAR, column_size_bytes BIGINT, value_count BIGINT, null_count BIGINT, min_value VARCHAR, max_value VARCHAR, contains_nan BOOLEAN, extra_stats VARCHAR);;
CREATE TABLE ducklake_inlined_data_tables(table_id BIGINT NOT NULL, table_name VARCHAR NOT NULL, schema_version BIGINT NOT NULL);;
CREATE TABLE ducklake_macro(schema_id BIGINT, macro_id BIGINT, macro_name VARCHAR, begin_snapshot BIGINT, end_snapshot BIGINT);;
CREATE TABLE ducklake_macro_impl(macro_id BIGINT, impl_id BIGINT, dialect VARCHAR, "sql" VARCHAR, "type" VARCHAR);;
CREATE TABLE ducklake_macro_parameters(macro_id BIGINT, impl_id BIGINT, column_id BIGINT, parameter_name VARCHAR, parameter_type VARCHAR, default_value VARCHAR, default_value_type VARCHAR);;
CREATE TABLE ducklake_metadata("key" VARCHAR NOT NULL, "value" VARCHAR NOT NULL, "scope" VARCHAR, scope_id BIGINT);;
CREATE TABLE ducklake_name_mapping(mapping_id BIGINT, column_id BIGINT, source_name VARCHAR, target_field_id BIGINT, parent_column BIGINT, is_partition BOOLEAN);;
CREATE TABLE ducklake_partition_column(partition_id BIGINT NOT NULL, table_id BIGINT NOT NULL, partition_key_index BIGINT NOT NULL, column_id BIGINT NOT NULL, "transform" VARCHAR NOT NULL);;
CREATE TABLE ducklake_partition_info(partition_id BIGINT NOT NULL, table_id BIGINT NOT NULL, begin_snapshot BIGINT NOT NULL, end_snapshot BIGINT);;
CREATE TABLE ducklake_schema(schema_id BIGINT DEFAULT(nextval('ducklake_schema_id_seq')) PRIMARY KEY, schema_uuid UUID DEFAULT(uuid()), schema_name VARCHAR NOT NULL, path VARCHAR DEFAULT('') NOT NULL, path_is_relative BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL, begin_snapshot BIGINT NOT NULL, end_snapshot BIGINT);;
CREATE TABLE ducklake_schema_versions(begin_snapshot BIGINT NOT NULL, schema_version BIGINT NOT NULL, table_id BIGINT NOT NULL, UNIQUE(table_id, begin_snapshot));;
CREATE TABLE ducklake_snapshot(snapshot_id BIGINT PRIMARY KEY, snapshot_time TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), schema_version BIGINT DEFAULT(0) NOT NULL, next_catalog_id BIGINT DEFAULT(1) NOT NULL, next_file_id BIGINT DEFAULT(0) NOT NULL);;
CREATE TABLE ducklake_snapshot_changes(snapshot_id BIGINT PRIMARY KEY, changes_made VARCHAR, author VARCHAR, commit_message VARCHAR, commit_extra_info VARCHAR);;
CREATE TABLE ducklake_sort_expression(sort_id BIGINT NOT NULL, table_id BIGINT NOT NULL, sort_key_index BIGINT NOT NULL, expression VARCHAR NOT NULL, dialect VARCHAR NOT NULL, sort_direction VARCHAR NOT NULL, null_order VARCHAR NOT NULL);;
CREATE TABLE ducklake_sort_info(sort_id BIGINT NOT NULL, table_id BIGINT NOT NULL, begin_snapshot BIGINT NOT NULL, end_snapshot BIGINT);;
CREATE TABLE ducklake_table(table_id BIGINT DEFAULT(nextval('ducklake_table_id_seq')) PRIMARY KEY, table_uuid UUID DEFAULT(uuid()), schema_id BIGINT NOT NULL, table_name VARCHAR NOT NULL, path VARCHAR DEFAULT('') NOT NULL, path_is_relative BOOLEAN DEFAULT(CAST('t' AS BOOLEAN)) NOT NULL, begin_snapshot BIGINT NOT NULL, end_snapshot BIGINT);;
CREATE TABLE ducklake_table_column_stats(table_id BIGINT NOT NULL, column_id BIGINT NOT NULL, contains_null BOOLEAN, contains_nan BOOLEAN, min_value VARCHAR, max_value VARCHAR, extra_stats VARCHAR);;
CREATE TABLE ducklake_table_stats(table_id BIGINT PRIMARY KEY, record_count BIGINT DEFAULT(0) NOT NULL, next_row_id BIGINT DEFAULT(0) NOT NULL, file_size_bytes BIGINT DEFAULT(0) NOT NULL);;
CREATE TABLE ducklake_tag(object_id BIGINT, begin_snapshot BIGINT, end_snapshot BIGINT, "key" VARCHAR, "value" VARCHAR);;
CREATE TABLE ducklake_view(view_id BIGINT, view_uuid UUID, begin_snapshot BIGINT, end_snapshot BIGINT, schema_id BIGINT, view_name VARCHAR, dialect VARCHAR, "sql" VARCHAR, column_aliases VARCHAR);;
CREATE INDEX idx_file_partition_value_table_key ON ducklake_file_partition_value(table_id, partition_key_index);;

